"""Demo: the general dimension law of the suspension tower.

Builds finite free Z/2-complexes and verifies dim S^k(K) = dim K + k over
several bases (not only octahedral), confirming that "+1 per suspension" is a
structural property of the suspension operation itself.
"""
from __future__ import annotations
from itertools import combinations
from typing import Callable, FrozenSet, Iterable, List

Face = FrozenSet[object]


class Complex:
    def __init__(self, vertices: Iterable[object], is_face: Callable[[Face], bool]) -> None:
        self.vertices: List[object] = list(vertices)
        self.is_face = is_face

    def dimension(self) -> int:
        best = -1
        vs = self.vertices
        for r in range(len(vs) + 1):
            for c in combinations(vs, r):
                if self.is_face(frozenset(c)):
                    best = max(best, r - 1)
        return best


def suspend(K: Complex) -> Complex:
    verts = [("L", v) for v in K.vertices] + [("A", 0), ("A", 1)]

    def is_face(s: Face) -> bool:
        base = frozenset(v[1] for v in s if v[0] == "L")
        apex = [v[1] for v in s if v[0] == "A"]
        return K.is_face(base) and len(apex) <= 1

    return Complex(verts, is_face)


def octahedral(n: int) -> Complex:
    verts = [(i, b) for i in range(n + 1) for b in (0, 1)]
    def is_face(s: Face) -> bool:
        axes = [i for (i, _b) in s]
        return len(axes) == len(set(axes))
    return Complex(verts, is_face)


def simplex(m: int) -> Complex:
    # A non-spherical base: full simplex on m+1 vertices with a trivial free flip
    # realized by pairing vertices; here we just test dimension bookkeeping.
    verts = list(range(m + 1))
    return Complex(verts, lambda s: True)


if __name__ == "__main__":
    for base_name, base in [("Oct(0)", octahedral(0)), ("Oct(2)", octahedral(2)),
                             ("Simplex(3)", simplex(3))]:
        d0 = base.dimension()
        cur = base
        print(f"base {base_name}: dim = {d0}")
        for k in range(1, 4):
            cur = suspend(cur)
            print(f"  dim S^{k} = {cur.dimension()} (expected {d0 + k})")

"""Demo: iterated combinatorial Borsuk-Ulam obstruction.

Exhaustively searches for an equivariant simplicial map from the k-fold
suspension of the 0-sphere onto the 0-sphere, confirming that none exists for
k >= 1 while the identity exists for k = 0.
"""
from __future__ import annotations
from itertools import combinations, product
from typing import Callable, FrozenSet, List

Face = FrozenSet[object]


class Complex:
    def __init__(self, vertices, alpha, is_face) -> None:
        self.vertices: List[object] = list(vertices)
        self.alpha: Callable[[object], object] = alpha
        self.is_face: Callable[[Face], bool] = is_face

    def faces(self) -> List[Face]:
        out: List[Face] = []
        for r in range(len(self.vertices) + 1):
            for c in combinations(self.vertices, r):
                if self.is_face(frozenset(c)):
                    out.append(frozenset(c))
        return out


def octahedral(n: int) -> Complex:
    verts = [(i, b) for i in range(n + 1) for b in (0, 1)]
    return Complex(verts, lambda v: (v[0], 1 - v[1]),
                   lambda s: len({i for (i, _b) in s}) == len(s))


def suspend(K: Complex) -> Complex:
    verts = [("L", v) for v in K.vertices] + [("A", 0), ("A", 1)]
    def alpha(v):
        return ("L", K.alpha(v[1])) if v[0] == "L" else ("A", 1 - v[1])
    def is_face(s: Face) -> bool:
        base = frozenset(v[1] for v in s if v[0] == "L")
        apex = [v[1] for v in s if v[0] == "A"]
        return K.is_face(base) and len(apex) <= 1
    return Complex(verts, alpha, is_face)


def has_equivariant_map(src: Complex, dst: Complex) -> bool:
    for choice in product(dst.vertices, repeat=len(src.vertices)):
        f = dict(zip(src.vertices, choice))
        if all(f[src.alpha(v)] == dst.alpha(f[v]) for v in src.vertices) and \
           all(dst.is_face(frozenset(f[v] for v in s)) for s in src.faces()):
            return True
    return False


if __name__ == "__main__":
    S0 = octahedral(0)
    tower = S0
    print("k=0: map to Oct(0) exists?", has_equivariant_map(tower, S0))
    for k in range(1, 3):
        tower = suspend(tower)
        print(f"k={k}: map to Oct(0) exists?", has_equivariant_map(tower, S0))

