  for each sign vector sigma in {0,1}^(n+1):
    facet <- { (i, sigma[i]) : i = 0..n }
    append facet to facets
  return facets     # exactly 2^(n+1) of them

function EXISTS_EQUIVARIANT_MAP(src, dst):
  for each function f: src.vertices -> dst.vertices:
    if forall v: f(src.alpha(v)) == dst.alpha(f(v)) and
       forall face s of src: dst.is_face(f(s)):
      return True
  return False

function SUSPEND(K):
  V' <- { Left(v) : v in K.vertices } U { Apex0, Apex1 }
  alpha'(Left(v)) = Left(K.alpha(v));  alpha'(Apex_b) = Apex_{1-b}
  is_face'(T) = K.is_face(base(T)) and |apexes(T)| <= 1
  return (V', alpha', is_face')

function TOWER(K, k):
  cur <- K
  repeat k times: cur <- SUSPEND(cur)
  return cur

